#[test]
fn test_find_meta_list_value_in_bare_frontmatter() {
    // Regression: indented YAML list items (`  - foo`) under bare frontmatter
    // were being stripped by the wrapper, so `--meta depends=foo` returned
    // nothing for bare-frontmatter docs even though fenced docs worked.
    let dir = setup_workspace_with_bare_frontmatter();

    write(
        dir.path().join("bare.md"),
        indoc! {"
            title: Bare Doc
            depends:
              - foo
              - bar

            Body.
        "},
    )
    .unwrap();

    write(
        dir.path().join("fenced.md"),
        indoc! {"
            ---
            title: Fenced Doc
            depends:
              - foo
            ---

            Body.
        "},
    )
    .unwrap();

