    // were being stripped by the wrapper, so `--meta depends=foo` returned
    // nothing for bare-frontmatter docs even though fenced docs worked.
    let dir = setup_workspace_with_bare_frontmatter();

    write(
        dir.path().join("bare.md"),
        indoc! {"
            title: Bare Doc
            depends:
              - foo
              - bar

            Body.
        "},
    )
    .unwrap();

    write(
        dir.path().join("fenced.md"),
        indoc! {"
            ---
            title: Fenced Doc
            depends:
              - foo
            ---

            Body.
        "},
    )
    .unwrap();

    write(
        dir.path().join("unrelated.md"),
        indoc! {"
            title: Other
            depends:
              - baz

            Body.
        "},
    )
    .unwrap();

    let (stdout, stderr, success) =
        run_iwe(dir.path(), &["--meta", "depends=foo", "-f", "keys"]);

    assert!(success, "stderr: {}", stderr);

    let keys: Vec<&str> = stdout.lines().collect();
    assert!(keys.contains(&"bare"), "bare doc should match: {:?}", keys);
    assert!(keys.contains(&"fenced"), "fenced doc should match: {:?}", keys);
    assert!(!keys.contains(&"unrelated"), "unrelated must not match: {:?}", keys);
}

