// Preserve all header lines verbatim — indented lines (`  - item`,
// multi-line scalars, etc.) are legitimate YAML continuations and must
// not be stripped, otherwise list values like `depends:\n  - foo` get
// silently dropped before pulldown-cmark sees the metadata block.
if rest.is_empty() {
    Cow::Owned(format!("---\n{}\n---\n", header))
} else {
    Cow::Owned(format!("---\n{}\n---\n\n{}", header, rest))
}

